1	package darksafe
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"reflect"
10		"strings"
11		"testing"
12		"unicode/utf8"
13	)
14	
15	// invalidByte is a lone byte that is never valid UTF-8 on its own.
16	const invalidByte = "\xff"
17	
18	// anotherInvalidByte renders identically under JSON replacement but is a
19	// different raw byte.
20	const anotherInvalidByte = "\xfe"
21	
22	// replacementRune is a genuine U+FFFD code point: valid UTF-8, unlike the
23	// lone invalid bytes.
24	const replacementRune = string(rune(0xFFFD))
25	
26	// hashEnvelope is the historical fingerprint envelope struct the legacy
27	// JSON fingerprint family was computed over. Production no longer names
28	// it — the single record field table (record_fields.go) defines the
29	// envelope now — but the tests keep it as an independent oracle: if the
30	// table-driven JSON encoder ever drifted from the historical
31	// encoding/json output, the comparisons against legacyJSONFingerprint
32	// would catch it.
33	type hashEnvelope struct {
34		Org             string          `json:"org"`
35		Seq             int             `json:"seq"`
36		Kind            string          `json:"kind"`
37		Change          *PolicyChange   `json:"change,omitempty"`
38		Decision        *DecisionRecord `json:"decision,omitempty"`
39		PrevFingerprint string          `json:"prev"`
40	}
41	
42	// legacyJSONFingerprint is the exact fingerprint algorithm used before
43	// the raw-content integrity fix: encoding/json over the envelope. Tests
44	// use it to prove valid-UTF-8 records keep byte-identical fingerprints.
45	func legacyJSONFingerprint(r *AuditRecord) string {
46		b, err := json.Marshal(&hashEnvelope{
47			Org:             r.Org,
48			Seq:             r.Seq,
49			Kind:            r.Kind,
50			Change:          r.Change,
51			Decision:        r.Decision,
52			PrevFingerprint: r.PrevFingerprint,
53		})
54		if err != nil {
55			panic(err)
56		}
57		sum := sha256.Sum256(b)
58		return hex.EncodeToString(sum[:])
59	}
60	
61	// cloneExportedRecords deep-copies a record set so mutating any string
62	// field or roles/matched/policies slice in the copy never reaches the
63	// original. encoding/json cannot be used for this: it would "repair" the
64	// invalid bytes under test.
65	func cloneExportedRecords(in []AuditRecord) []AuditRecord {
66		out := make([]AuditRecord, len(in))
67		for i, r := range in {
68			cp := r
69			if r.Change != nil {
70				c := *r.Change
71				if r.Change.Policies != nil {
72					c.Policies = append([]Policy(nil), r.Change.Policies...)
73				}
74				cp.Change = &c
75			}
76			if r.Decision != nil {
77				d := *r.Decision
78				if r.Decision.Request.Subject.Roles != nil {
79					d.Request.Subject.Roles = append([]string(nil), r.Decision.Request.Subject.Roles...)
80				}
81				if r.Decision.Decision.Matched != nil {
82					d.Decision.Matched = append([]string(nil), r.Decision.Decision.Matched...)
83				}
84				cp.Decision = &d
85			}
86			out[i] = cp
87		}
88		return out
89	}
90	
91	// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
92	// with strings carrying invalid UTF-8 in every policy and request string
93	// reachable through the public surface. Acceptance must be unchanged, no
94	// byte may be deleted, replaced or normalized, and query/export/offline
95	// review must observe the exact submitted bytes.
96	func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
97		s := NewStore()
98		submitted := Policy{
99			ID:      "策" + invalidByte + "略",
100			Subject: "用" + invalidByte + "戶",
101			Action:  "读" + invalidByte,
102			Scope:   "org/a/资" + invalidByte + "料",
103			Effect:  EffectAllow,
104		}
105		v, err := s.Publish("acme", 0, []Policy{submitted})
106		if err != nil || v != 1 {
107			t.Fatalf("publish with invalid UTF-8 = %d, %v; want accepted", v, err)
108		}
109	
110		req := OrgRequest{
111			SubjectOrg:  "acme",
112			ResourceOrg: "acme",
113			Subject: Subject{
114				ID:    "用" + invalidByte + "戶",
115				Kind:  "外" + invalidByte + "部",
116				Roles: []string{"角" + invalidByte + "色", "普通角色"},
117			},
118			Resource: Resource{ID: "资" + invalidByte + "源", Scope: submitted.Scope},
119			Action:   submitted.Action,
120		}
121		d := s.Decide("acme", req)
122		if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
123			t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
124		}
125		if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
126			t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
127		}
128		if !strings.Contains(d.Matched[0], invalidByte) {
129			t.Fatal("invalid byte normalized out of matched policy id")
130		}
131	
132		// A rollback republishes the invalid-byte content and records it.
133		if rv, err := s.Rollback("acme", 1, 1); err != nil || rv != 2 {
134			t.Fatalf("rollback = %d, %v", rv, err)
135		}
136		// A normal record and an invalid-byte record coexist in one export.
137		if _, err := s.Publish("acme", 2, nil); err != nil {
138			t.Fatal(err)
139		}
140		plain := s.Decide("acme", request("acme", "plain", "r1", "org/a", "read"))
141		if plain.Allowed {
142			t.Fatalf("plain request under empty version must deny: %+v", plain)
143		}
144	
145		recs, cp, err := s.AuditExport("acme", 0)
146		if err != nil {
147			t.Fatal(err)
148		}
149		if err := VerifyAudit("acme", recs, cp); err != nil {
150			t.Fatalf("export with invalid UTF-8 must verify: %v", err)
151		}
152	
153		// The export is byte-for-byte the submitted content at every level.
154		gotPolicy := recs[0].Change.Policies[0]
155		if !reflect.DeepEqual(gotPolicy, submitted) {
156			t.Fatalf("policy bytes = %+v, want %+v", gotPolicy, submitted)
157		}
158		gotReq := recs[1].Decision.Request
159		if !reflect.DeepEqual(gotReq, req) {
160			t.Fatalf("request bytes = %+v, want %+v", gotReq, req)
161		}
162		if !reflect.DeepEqual(recs[1].Decision.Decision, d) {
163			t.Fatalf("decision bytes = %+v, want %+v", recs[1].Decision.Decision, d)
164		}
165		if !reflect.DeepEqual(recs[2].Change.Policies, []Policy{submitted}) {
166			t.Fatal("rollback record lost the published raw bytes")
167		}
168		for _, haystack := range []string{
169			gotPolicy.ID, gotPolicy.Subject, gotPolicy.Action, gotPolicy.Scope,
170			gotReq.Subject.ID, gotReq.Subject.Kind, gotReq.Subject.Roles[0],
171			gotReq.Resource.ID, gotReq.Resource.Scope, gotReq.Action,
172		} {
173			if !strings.Contains(haystack, invalidByte) {
174				t.Fatalf("invalid byte was deleted or normalized in %q", haystack)
175			}
176		}
177	
178		// Paged queries return the same bytes.
179		page, err := s.AuditQuery("acme", 1, 1, "", "")
180		if err != nil {
181			t.Fatal(err)
182		}
183		queried := append([]AuditRecord(nil), page.Records...)
184		for page.Next != 0 {
185			page, err = s.AuditPage(page.Checkpoint, page.Next, 1, "", "")
186			if err != nil {
187				t.Fatal(err)
188			}
189			queried = append(queried, page.Records...)
190		}
191		if !reflect.DeepEqual(queried, recs) {
192			t.Fatal("paged query bytes differ from the export bytes")
193		}
194	
195		// Offline review recomputes from the raw request and recorded version.
196		review, err := RecheckDecisionOffline("acme", recs, cp, 2)
197		if err != nil {
198			t.Fatalf("offline review: %v", err)
199		}
200		if !review.Consistent || !reflect.DeepEqual(review.Original, d) ||
201			!reflect.DeepEqual(review.Recomputed, d) {
202			t.Fatalf("offline review = %+v, want consistent with %+v", review, d)
203		}
204		if !strings.Contains(review.Recomputed.Matched[0], invalidByte) {
205			t.Fatal("offline review normalized the matched policy id")
206		}
207	
208		// An organization whose name itself carries invalid bytes: genesis
209		// checkpoint, isolation and offline review all still work.
210		weirdOrg := "组" + invalidByte + "织"
211		if _, err := s.Publish(weirdOrg, 0, []Policy{submitted}); err != nil {
212			t.Fatalf("publish into invalid-UTF-8 org: %v", err)
213		}
214		wreq := req
215		wreq.SubjectOrg = weirdOrg
216		wreq.ResourceOrg = weirdOrg
217		if d := s.Decide(weirdOrg, wreq); !d.Allowed {
218			t.Fatalf("decision inside invalid-UTF-8 org = %+v", d)
219		}
220		wrecs, wcp, err := s.AuditExport(weirdOrg, 0)
221		if err != nil {
222			t.Fatal(err)
223		}
224		if err := VerifyAudit(weirdOrg, wrecs, wcp); err != nil {
225			t.Fatalf("invalid-UTF-8 org chain: %v", err)
226		}
227		if wr, err := RecheckDecisionOffline(weirdOrg, wrecs, wcp, 2); err != nil || !wr.Consistent {
228			t.Fatalf("invalid-UTF-8 org offline review = %+v, %v", wr, err)
229		}
230		// The sequence-0 root checkpoint is the genesis for that org too.
231		empty, emptyCP, err := s.AuditExport(weirdOrg+"-none", 0)
232		if err != nil {
233			t.Fatal(err)
234		}
235		if err := VerifyAudit(weirdOrg+"-none", empty, emptyCP); err != nil {
236			t.Fatalf("genesis checkpoint: %v", err)
237		}
238	}
239	
240	// TestInvalidBytesFingerprintBuildsChainOfMixedRecords checks ordinary
241	// and invalid-byte records chaining together: ordinary records keep the
242	// legacy JSON fingerprint, the invalid-byte record verifies and is pinned
243	// by the checkpoint, and tampering either family fails with
244	// ErrInvalidRange.
245	func TestInvalidBytesFingerprintBuildsChainOfMixedRecords(t *testing.T) {
246		s := NewStore()
247		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
248		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
249		s.Publish("acme", 1, []Policy{{
250			ID:      "策" + invalidByte + "略",
251			Subject: "用" + invalidByte + "戶",
252			Action:  "read",
253			Scope:   "org/a",
254			Effect:  EffectAllow,
255		}})
256		recs, cp, err := s.AuditExport("acme", 0)
257		if err != nil {
258			t.Fatal(err)
259		}
260		if err := VerifyAudit("acme", recs, cp); err != nil {
261			t.Fatalf("mixed chain: %v", err)
262		}
263		if got := fingerprintFor(&recs[0]); got != legacyJSONFingerprint(&recs[0]) {
264			t.Fatal("valid-UTF-8 record changed fingerprint family")
265		}
266		if got := fingerprintFor(&recs[1]); got != legacyJSONFingerprint(&recs[1]) {
267			t.Fatal("valid-UTF-8 decision changed fingerprint family")
268		}
269		if got := fingerprintFor(&recs[2]); got == legacyJSONFingerprint(&recs[2]) {
270			t.Fatal("invalid-byte record still uses the JSON fingerprint")
271		}
272		if recs[2].Fingerprint != cp.Fingerprint {
273			t.Fatal("checkpoint does not pin the raw-encoded final record")
274		}
275		bad := cloneExportedRecords(recs)
276		bad[2].Change.Policies[0].ID = strings.Replace(bad[2].Change.Policies[0].ID, invalidByte, anotherInvalidByte, 1)
277		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
278			t.Fatalf("tampered invalid-byte record err = %v, want ErrInvalidRange", err)
279		}
280		bad = cloneExportedRecords(recs)
281		bad[0].Change.Policies[0].ID = "p2"
282		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
283			t.Fatalf("tampered ordinary record err = %v, want ErrInvalidRange", err)
284		}
285	}
