287	// buildInvalidByteChain constructs a chain where every fingerprinted
288	// string field can be probed. Record 1 is a policy change, record 2 the
289	// reviewed decision with an invalid byte embedded between legal Chinese
290	// in every nested field and list, record 3 a decision after the target.
291	func buildInvalidByteChain(t *testing.T) (string, []AuditRecord, Checkpoint) {
292		t.Helper()
293		org := "组" + invalidByte + "织"
294		subjectID := "身" + invalidByte + "份"
295		action := "动" + invalidByte + "作"
296		scope := "范" + invalidByte + "围"
297		p1 := Policy{
298			ID:      "策" + invalidByte + "id",
299			Subject: subjectID,
300			Action:  action,
301			Scope:   scope,
302			Effect:  EffectAllow,
303		}
304		p2 := Policy{
305			ID:      "命" + invalidByte + "中二",
306			Subject: subjectID,
307			Action:  action,
308			Scope:   scope,
309			Effect:  EffectAllow,
310		}
311		prev := genesisFingerprint(org)
312		rec1 := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
313			Version: 1, Policies: []Policy{p1, p2},
314		}, nil, prev)
315		prev = rec1.Fingerprint
316		rec2 := syntheticRecord(org, 2, AuditDecision, nil, &DecisionRecord{
317			Request: OrgRequest{
318				SubjectOrg:  org,
319				ResourceOrg: org,
320				Subject: Subject{
321					ID:    subjectID, // invalid byte between legal Chinese
322					Kind:  "类" + invalidByte + "型",
323					Roles: []string{"角" + invalidByte + "色", "正常角色"},
324				},
325				Resource: Resource{ID: "资" + invalidByte + "源", Scope: scope},
326				Action:   action,
327			},
328			Decision: Decision{
329				Allowed: true,
330				Reason:  "理" + invalidByte + "由",
331				Matched: []string{p2.ID, p1.ID}, // sorted by raw bytes
332				Version: 1,
333			},
334		}, prev)
335		prev = rec2.Fingerprint
336		rec3 := syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
337			Request: OrgRequest{
338				SubjectOrg:  org,
339				ResourceOrg: org,
340				Subject:     Subject{ID: "尾" + invalidByte + "随"},
341				Resource:    Resource{ID: "later", Scope: "org/a"},
342				Action:      "read",
343			},
344			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Version: 1},
345		}, prev)
346		recs := []AuditRecord{rec1, rec2, rec3}
347		cp := Checkpoint{Org: org, EndSeq: 3, Fingerprint: rec3.Fingerprint}
348		if err := VerifyAudit(org, recs, cp); err != nil {
349			t.Fatalf("test fixture must verify: %v", err)
350		}
351		return org, recs, cp
