package darksafe

import (
	"bytes"
	"encoding/binary"
	"testing"
)

// oldEncoder reimplements the pre-refactor canonical encoder with the two
// separately-maintained list routines, to prove the shared helper emits
// byte-identical output. Temporary verification scaffold.
type oldEncoder struct{ buf []byte }

func (e *oldEncoder) tag(t fingerprintTag)  { e.buf = append(e.buf, byte(t)) }
func (e *oldEncoder) int64Tag(t fingerprintTag, v int64) {
	e.tag(t)
	var b [8]byte
	binary.BigEndian.PutUint64(b[:], uint64(v))
	e.buf = append(e.buf, b[:]...)
}
func (e *oldEncoder) boolTag(t fingerprintTag, v bool) {
	e.tag(t)
	if v {
		e.buf = append(e.buf, 1)
	} else {
		e.buf = append(e.buf, 0)
	}
}
func (e *oldEncoder) rawString(s string) {
	e.tag(tagString)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(s)))
	e.buf = append(e.buf, b[:]...)
	e.buf = append(e.buf, s...)
}
func (e *oldEncoder) stringList(items []string) {
	e.tag(tagStringList)
	if items == nil {
		e.buf = append(e.buf, 0)
		return
	}
	e.buf = append(e.buf, 1)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(items)))
	e.buf = append(e.buf, b[:]...)
	for _, s := range items {
		e.rawString(s)
	}
}
func (e *oldEncoder) policy(p Policy) {
	e.tag(tagPolicy)
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString:
			e.rawString(f.getString(p))
		case policyFieldOptionalString:
			if v := f.getString(p); v != "" {
				e.rawString(v)
			}
		case policyFieldBool:
			e.boolTag(tagBool, f.getBool(p))
		}
	}
}
func (e *oldEncoder) policyList(policies []Policy) {
	e.tag(tagPolicyList)
	if policies == nil {
		e.buf = append(e.buf, 0)
		return
	}
	e.buf = append(e.buf, 1)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(policies)))
	e.buf = append(e.buf, b[:]...)
	for _, p := range policies {
		e.policy(p)
	}
}
func (e *oldEncoder) change(c *PolicyChange) {
	e.tag(tagChange)
	if c == nil {
		return
	}
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(c)))
		case changeFieldPolicyList:
			e.policyList(f.getPolicies(c))
		case changeFieldBool:
			e.boolTag(tagBool, f.getBool(c))
		}
	}
}
func (e *oldEncoder) decisionRecord(d *DecisionRecord) {
	e.tag(tagDecisionRecord)
	if d == nil {
		return
	}
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.groupTag != 0 {
			e.tag(f.groupTag)
		}
		switch f.kind {
		case decisionFieldString:
			e.rawString(f.getString(d))
		case decisionFieldStringList:
			e.stringList(f.getList(d))
		case decisionFieldBool:
			e.boolTag(tagBool, f.getBool(d))
		case decisionFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(d)))
		}
	}
}
func oldEncode(r *AuditRecord) []byte {
	e := &oldEncoder{buf: []byte(rawEnvelopePrefix)}
	e.tag(tagEnvelope)
	for i := range recordFields {
		f := &recordFields[i]
		if f.jsonKey == "" {
			continue
