		{{ID: "策\xff略", Subject: "用\xfe戶", Action: "读", Scope: "范\x00围", Effect: EffectAllow, Recursive: true}},
		{{ID: "p1", Subject: "u", Action: "a", Scope: "s", Effect: EffectDeny},
			{ID: "p1", Subject: "u", Action: "a", Scope: "s", Effect: EffectDeny, ResourceID: "res\xff"}},
		{{ID: "", Subject: "", Action: "", Scope: "", Effect: EffectAllow, ResourceID: "r"}},
	}
	prev := genesisFingerprint(org)
	seq := 0
	mk := func(change *PolicyChange, dec *DecisionRecord) *AuditRecord {
		seq++
