	}
	for _, roles := range shapes {
		for _, matched := range shapes {
			dec := &DecisionRecord{
				Request: OrgRequest{
					SubjectOrg:  org,
					ResourceOrg: org,
					Subject:     Subject{ID: "身\xff份", Kind: "类\xfe型", Roles: roles},
					Resource:    Resource{ID: "资\xff源", Scope: "s", ID2unrelated: ""},
					Action:      "动\xff作",
				},
				Decision: Decision{Allowed: true, Reason: "理\xff由", Matched: matched, Version: 9},
			}
			r := mk(nil, dec)
			if got, want := encodeCanonical(r), oldEncode(r); !bytes.Equal(got, want) {
				t.Fatalf("roles=%v matched=%v:\nnew %x\nold %x", roles, matched, got, want)
			}
		}
	}
